CREATE TYPE "enrollment_status" AS ENUM (
  'active',
  'dropped',
  'completed'
);

CREATE TYPE "day_of_week" AS ENUM (
  'Sunday',
  'Monday',
  'Tuesday',
  'Wednesday',
  'Thursday',
  'Friday',
  'Saturday'
);

CREATE TABLE "departments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar UNIQUE NOT NULL,
  "head_instructor_id" integer
);

CREATE TABLE "instructors" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_name" varchar NOT NULL,
  "email" varchar UNIQUE NOT NULL,
  "department_id" integer NOT NULL,
  "hired_at" date
);

CREATE TABLE "students" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_name" varchar NOT NULL,
  "email" varchar UNIQUE NOT NULL,
  "date_of_birth" date,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "courses" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar UNIQUE NOT NULL,
  "title" varchar NOT NULL,
  "credit_hours" integer,
  "department_id" integer NOT NULL,
  "instructor_id" integer
);

CREATE TABLE "enrollments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "student_id" integer NOT NULL,
  "course_id" integer NOT NULL,
  "enrolled_at" timestamp DEFAULT (now()),
  "grade" decimal(5,2),
  "status" enrollment_status NOT NULL DEFAULT 'active'
);

CREATE TABLE "course_prerequisites" (
  "course_id" integer NOT NULL,
  "prerequisite_course_id" integer NOT NULL,
  PRIMARY KEY ("course_id", "prerequisite_course_id")
);

CREATE TABLE "classrooms" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "building" varchar NOT NULL,
  "room_number" varchar NOT NULL,
  "capacity" integer NOT NULL
);

CREATE TABLE "course_meetings" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "course_id" integer NOT NULL,
  "classroom_id" integer NOT NULL,
  "day_of_week" day_of_week NOT NULL,
  "start_time" time NOT NULL,
  "end_time" time NOT NULL
);

CREATE UNIQUE INDEX ON "enrollments" ("student_id", "course_id");

CREATE UNIQUE INDEX ON "classrooms" ("building", "room_number");

COMMENT ON TABLE "departments" IS 'Each department can have one instructor as its head.';

COMMENT ON TABLE "instructors" IS 'Each instructor belongs to one department.';

COMMENT ON TABLE "students" IS 'Stores student information.';

COMMENT ON TABLE "courses" IS 'Each course belongs to one department and may have one instructor.';

COMMENT ON TABLE "enrollments" IS 'Stores student course enrollment information.';

COMMENT ON TABLE "course_prerequisites" IS 'Connects courses to their prerequisite courses.';

COMMENT ON TABLE "classrooms" IS 'Stores classroom information.';

COMMENT ON TABLE "course_meetings" IS 'Stores course meeting schedules and assigned classrooms.';

ALTER TABLE "instructors" ADD FOREIGN KEY ("department_id") REFERENCES "departments" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "courses" ADD FOREIGN KEY ("department_id") REFERENCES "departments" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "courses" ADD FOREIGN KEY ("instructor_id") REFERENCES "instructors" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "enrollments" ADD FOREIGN KEY ("student_id") REFERENCES "students" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "enrollments" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "departments" ADD FOREIGN KEY ("head_instructor_id") REFERENCES "instructors" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "course_prerequisites" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "course_prerequisites" ADD FOREIGN KEY ("prerequisite_course_id") REFERENCES "courses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "course_meetings" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "course_meetings" ADD FOREIGN KEY ("classroom_id") REFERENCES "classrooms" ("id") DEFERRABLE INITIALLY IMMEDIATE;
